import { PROGRAMME_PENDING_MESSAGE, SESSION_EXPIRED_MESSAGE, corsHeaders } from '../_shared/hub-core.ts';
import { bootstrapHub, saveSharedHubFeedback } from '../_shared/hub-service.ts';
import { SupabaseHubRepository } from '../_shared/supabase-repository.ts';
import { adminClient, cryptoPort } from '../_shared/runtime.ts';

function json(origin: string, status: number, body: Record<string, unknown>) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders(origin), 'Content-Type': 'application/json', 'Cache-Control': 'no-store' } });
}

Deno.serve(async request => {
  const origin = request.headers.get('origin') || '';
  const cors = corsHeaders(origin);
  if (request.method === 'OPTIONS') return new Response('ok', { status: cors['Access-Control-Allow-Origin'] ? 200 : 403, headers: cors });
  if (request.method !== 'POST' || !cors['Access-Control-Allow-Origin']) return json(origin, 403, { error: 'Request not allowed.' });

  try {
    const body = await request.json();
    const repository = new SupabaseHubRepository(adminClient());
    let result;
    if (body?.action === 'bootstrap') result = await bootstrapHub({ token: request.headers.get('x-du-session') || '', repository, cryptoPort });
    else if (body?.action === 'save-feedback') result = await saveSharedHubFeedback({ token: request.headers.get('x-du-session') || '', feedbackType: body.feedbackType, input: body.feedback, repository, cryptoPort });
    else return json(origin, 400, { error: 'Unsupported request.' });
    return json(origin, 200, result);
  } catch (error) {
    if (error instanceof Error && error.message === SESSION_EXPIRED_MESSAGE) return json(origin, 401, { error: SESSION_EXPIRED_MESSAGE });
    if (error instanceof Error && error.message === PROGRAMME_PENDING_MESSAGE) return json(origin, 409, { error: PROGRAMME_PENDING_MESSAGE });
    if (error instanceof Error && error.message === 'Invalid feedback information.') return json(origin, 400, { error: error.message });
    console.error('hub-data failed', error);
    return json(origin, 500, { error: 'The Performance Hub is temporarily unavailable.' });
  }
});

export const ACCESS_DENIED_MESSAGE = 'Access code not recognized. Please contact Coach Du.';
export const PROGRAMME_PENDING_MESSAGE = 'Programme week is being prepared.';
export const SESSION_EXPIRED_MESSAGE = 'Your Hub session has expired. Enter your access code again.';

const PRODUCTION_ORIGINS = new Set([
  'https://duairlineseliteacademy.com',
  'https://www.duairlineseliteacademy.com',
  'https://hiktwkdfvlujszczthdu.supabase.co',
]);

const PROTOTYPE_ORIGINS = new Set([
  'http://terminal.local:4173',
  'https://du-airlines-performance-hub-pilot.light-auk-1409.chatgpt.site',
  'https://du-airlines-performance-hub-pilot.duchenge28.chatgpt.site',
]);

export function corsHeaders(origin = ''): Record<string, string> {
  const local = /^http:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin);
  const headers: Record<string, string> = {
    'Access-Control-Allow-Headers': 'authorization,apikey,content-type,x-du-session',
    'Access-Control-Allow-Methods': 'POST,OPTIONS',
    'Vary': 'Origin',
  };
  if (PRODUCTION_ORIGINS.has(origin) || PROTOTYPE_ORIGINS.has(origin) || local) {
    headers['Access-Control-Allow-Origin'] = origin;
  }
  return headers;
}

export function normalizeCode(value: unknown): string {
  return typeof value === 'string' ? value.trim().toLowerCase() : '';
}

export function validateLoginInput(input: { code?: unknown; view?: unknown }): { code: string; view: 'athlete' | 'staff' } {
  const code = normalizeCode(input?.code);
  const view = input?.view;
  if (code.length < 12 || code.length > 128 || (view !== 'athlete' && view !== 'staff')) {
    throw new Error(ACCESS_DENIED_MESSAGE);
  }
  return { code, view };
}

export function codeTypeForView(view: 'athlete' | 'staff'): 'cohort' | 'staff' {
  return view === 'staff' ? 'staff' : 'cohort';
}

export function isCodeUsable(record: any, view: 'athlete' | 'staff', now = new Date()): boolean {
  if (!record || record.status !== 'active' || !record.cohort_id) return false;
  if (record.code_type !== codeTypeForView(view)) return false;
  if (record.expires_at && new Date(record.expires_at).getTime() <= now.getTime()) return false;
  return true;
}

export function isSessionUsable(record: any, now = new Date()): boolean {
  if (!record || !record.cohort_id || record.revoked_at) return false;
  if (!record.expires_at || new Date(record.expires_at).getTime() <= now.getTime()) return false;
  return record.role === 'athlete' || record.role === 'staff';
}

export function prepareBundleForDelivery(bundle: any) {
  if (!bundle?.cohort || !bundle?.programme) return null;
  const published = bundle?.week
    && (bundle.week.status === 'live' || bundle.week.status === 'completed')
    && bundle.week.verification_status === 'verified'
    && bundle.week.published_at;
  if (published) return bundle;
  return { ...bundle, week: null, trainingDays: [], blocks: [], exercises: [] };
}

function unique<T>(values: T[]): T[] {
  return [...new Set(values)];
}

function firstText(blocks: any[], key: string): string {
  for (const block of blocks) {
    const value = block?.content?.[key];
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return '';
}

function prescriptionsFrom(blocks: any[]) {
  return blocks.flatMap(block => Array.isArray(block?.content?.prescriptions)
    ? block.content.prescriptions
        .filter((item: any) => typeof item?.exerciseCode === 'string' && item.exerciseCode.trim())
        .map((item: any) => ({
          sectionTitle: typeof block?.title === 'string' ? block.title.trim() : '',
          sectionOrder: Number.isFinite(block?.sort_order) ? block.sort_order : 0,
          exerciseCode: item.exerciseCode.trim(),
          dosage: typeof item.dosage === 'string' ? item.dosage : '',
          rest: typeof item.rest === 'string' ? item.rest : '',
          cues: typeof item.cues === 'string' ? item.cues : '',
          equipment: typeof item.equipment === 'string' ? item.equipment : '',
          alternativeExerciseCode: typeof item.alternativeExerciseCode === 'string' ? item.alternativeExerciseCode : '',
          ...(typeof item.originalExerciseCode === 'string' && item.originalExerciseCode
            ? { originalExerciseCode: item.originalExerciseCode } : {}),
          ...(typeof item.substitutionNote === 'string' && item.substitutionNote
            ? { substitutionNote: item.substitutionNote } : {}),
        }))
    : []);
}

function routinePlaylistsFrom(blocks: any[]) {
  return blocks.flatMap(block => Array.isArray(block?.content?.playlists) ? block.content.playlists : [])
    .filter((item: any) => {
      const id = typeof item?.id === 'string' && /^[A-Za-z0-9_-]{6,100}$/.test(item.id.trim());
      const url = typeof item?.url === 'string' && /^https:\/\/(www\.|m\.)?youtube\.com\/playlist\?[^\s]*\blist=[A-Za-z0-9_-]{6,100}(?:&[^\s]*)?$/i.test(item.url.trim());
      return id || url;
    })
    .map((item: any) => ({
      type: typeof item.type === 'string' && item.type.trim() ? item.type.trim() : 'routine',
      title: typeof item.title === 'string' && item.title.trim() ? item.title.trim() : 'Session Playlist',
      id: typeof item.id === 'string' && /^[A-Za-z0-9_-]{6,100}$/.test(item.id.trim()) ? item.id.trim() : '',
      url: typeof item.url === 'string' ? item.url.trim() : '',
    }));
}

export function shapeBootstrap(input: {
  role: 'athlete' | 'staff';
  cohort: any;
  programme: any;
  week: any;
  trainingDays: any[];
  blocks: any[];
  exercises: any[];
  personalNote?: string;
}) {
  const { role, cohort, programme, week } = input;
  const cohortPayload = {
    id: cohort.id,
    name: cohort.name,
    currentWeek: cohort.current_week,
    startDate: cohort.start_date || '',
  };
  if (!week) {
    const expectedSessions = Number.isInteger(cohort.expected_sessions_per_week)
      ? Math.min(7, Math.max(1, cohort.expected_sessions_per_week)) : 3;
    return {
      contentStatus: 'preparing',
      role,
      cohort: cohortPayload,
      programme: {
        id: programme.id,
        school: cohort.name,
        title: programme.name,
        sport: programme.sport || '',
        week: cohort.current_week,
        totalWeeks: programme.duration_weeks,
        weeklyObjective: 'Your programme week is being prepared.',
        athleteEducation: '',
        programmeNotes: '',
        coachGuidance: '',
        sessions: Array.from({ length: expectedSessions }, (_, index) => ({
          id: `preparing-day-${index + 1}`,
          day: `Day ${index + 1}`,
          title: 'Session being prepared',
          duration: '',
          objective: 'Coach Du will publish this session before your programme begins.',
          prescriptions: [],
          playlist: { id: '', url: '' },
          locked: true,
        })),
      },
      exercises: [],
    };
  }
  const trainingDays = [...(input.trainingDays || [])].sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
  const allBlocks = (input.blocks || []).map((block: any) => {
    const original = Array.isArray(block?.content?.items) ? block.content.items : [];
    const instructions = (Array.isArray(block?.content?.prescriptions) ? block.content.prescriptions : [])
      .filter((row: any) => !row?.exerciseCode && typeof row?.instruction === 'string' && row.instruction.trim())
      .map((row: any) => row.instruction);
    return {...block,content:{...(block.content || {}),items:[...original,...[...instructions, ...(typeof block?.content?.instruction === 'string' && block.content.instruction.trim() ? [block.content.instruction] : [])].filter((line: string) => !original.includes(line))]}};
  });

  const sessions = trainingDays.map((day, index) => {
    const blocks = allBlocks
      .filter(block => block.training_day_id === day.id)
      .sort((a, b) => (a.sort_order || 0) - (b.sort_order || 0));
    const items = blocks.flatMap(block => Array.isArray(block?.content?.items) ? block.content.items.filter((item: unknown) => typeof item === 'string') : []);
    const itemSections = blocks
      .filter(block => Array.isArray(block?.content?.items) && block.content.items.some((item: unknown) => typeof item === 'string'))
      .map(block => ({
        title: typeof block.title === 'string' ? block.title.trim() : 'Session Instructions',
        order: Number.isFinite(block.sort_order) ? block.sort_order : 0,
        items: block.content.items.filter((item: unknown) => typeof item === 'string'),
        // Keep the database's reviewed movement selection and original row scope.
        // URLs come from the current authorized library, never stale JSON URLs.
        videoLinks: (Array.isArray(block.content.video_links) ? block.content.video_links : [])
          .flatMap((link: any) => {
            if (!Number.isInteger(link?.item_index) || link.item_index < 0
              || typeof block.content.items[link.item_index] !== 'string') return [];
            const exercise = (input.exercises || []).find(ex => ex.active !== false && ex.name === link.exercise);
            if (!exercise) return [];
            const url = exercise.video_url || (exercise.video_id ? 'https://www.youtube.com/watch?v=' + exercise.video_id : '');
            return url ? [{itemIndex: block.content.items.slice(0, link.item_index).filter((item: unknown) => typeof item === 'string').length,
              title: exercise.name, code: exercise.code, url}] : [];
          }),
      }));
    const exerciseCodes = unique(blocks.flatMap(block => Array.isArray(block?.content?.exerciseCodes) ? block.content.exerciseCodes.filter((code: unknown) => typeof code === 'string') : []));
    const athleteNotes = blocks.map(block => block.athlete_note).filter((note: unknown) => typeof note === 'string' && note.trim());
    const staffNotes = blocks.map(block => block.staff_note).filter((note: unknown) => typeof note === 'string' && note.trim());
    const prescriptions = prescriptionsFrom(blocks);
    const session: Record<string, unknown> = {
      id: day.id,
      day: day.day_key || `Day ${index + 1}`,
      requirement: firstText(blocks, 'requirement') || 'Mandatory',
      title: day.title || `Day ${index + 1}`,
      duration: day.duration || '',
      focus: firstText(blocks, 'focus') || day.intensity || day.objective || '',
      objective: day.objective || '',
      why: firstText(blocks, 'why'),
      watch: firstText(blocks, 'watch'),
      items,
      itemSections,
      exerciseCodes,
      playlist: {
        id: day.playlist_id || '',
        url: day.playlist_url || '',
      },
      playlists: routinePlaylistsFrom(blocks),
      prescriptions,
      athleteNote: athleteNotes.join('\n'),
    };
    if (role === 'staff') session.staffNote = staffNotes.join('\n');
    return session;
  });

  const referencedCodes = new Set(allBlocks.flatMap(block => {
    const legacyCodes = Array.isArray(block?.content?.exerciseCodes) ? block.content.exerciseCodes : [];
    const prescriptionCodes = prescriptionsFrom([block]).flatMap(item => [item.exerciseCode, item.alternativeExerciseCode]);
    return [...legacyCodes, ...prescriptionCodes].filter(code => typeof code === 'string' && code.trim());
  }));
  const referencedNames = new Set(allBlocks.flatMap(block => (Array.isArray(block?.content?.video_links) ? block.content.video_links : []).map((link: any) => link?.exercise)));
  const exercises = (input.exercises || []).filter(exercise => exercise.active !== false && (referencedCodes.has(exercise.code) || referencedNames.has(exercise.name))).map(exercise => ({
    id: exercise.id,
    code: exercise.code,
    title: exercise.name,
    category: exercise.categories || (exercise.category_slug ? [exercise.category_slug] : []),
    videoId: exercise.video_id || '',
    videoUrl: exercise.video_url || '',
    description: exercise.description || '',
    purpose: exercise.purpose || '',
    coachingCues: exercise.coaching_cues || '',
    defaultDosage: exercise.default_dosage || '',
    order: exercise.display_order || 0,
    active: true,
  }));
  const staffGuidance = unique(allBlocks
    .map(block => block.staff_note)
    .filter((note: unknown) => typeof note === 'string' && note.trim()))
    .join(' ');
  const programmeNotes = [
    week.running_focus ? `Running: ${week.running_focus}` : '',
    week.strength_focus ? `Strength: ${week.strength_focus}` : '',
    week.event_focus ? `Event: ${week.event_focus}` : '',
  ].filter(Boolean).join(' • ');

  return {
    contentStatus: 'published',
    role,
    cohort: cohortPayload,
    programme: {
      id: programme.id,
      school: cohort.name,
      title: programme.name,
      sport: programme.sport || '',
      week: week.week_number,
      totalWeeks: programme.duration_weeks,
      phase: week.phase || '',
      scheduledFor: week.scheduled_for || '',
      weeklyObjective: week.weekly_objective || '',
      athleteEducation: week.athlete_education || '',
      programmeNotes: role === 'staff' ? programmeNotes : '',
      coachGuidance: role === 'staff' ? staffGuidance : '',
      personalNote: typeof input.personalNote === 'string' ? input.personalNote : '',
      sessions,
    },
    exercises,
  };
}

import {
  ACCESS_DENIED_MESSAGE,
  PROGRAMME_PENDING_MESSAGE,
  SESSION_EXPIRED_MESSAGE,
  isCodeUsable,
  isSessionUsable,
  prepareBundleForDelivery,
  shapeBootstrap,
  validateLoginInput,
} from './hub-core.ts';
import { saveFeedback } from './feedback-service.ts';

export async function exchangeAccessCode({ code, view, now = new Date(), repository, cryptoPort }: any) {
  let input;
  try {
    input = validateLoginInput({ code, view });
  } catch {
    throw new Error(ACCESS_DENIED_MESSAGE);
  }
  const codeHash = await cryptoPort.sha256(input.code);
  const record = await repository.findAccessCode(codeHash);
  if (!isCodeUsable(record, input.view, now)) throw new Error(ACCESS_DENIED_MESSAGE);
  const cohort = await repository.findCohort(record.cohort_id);
  if (!cohort || cohort.status !== 'live') throw new Error(ACCESS_DENIED_MESSAGE);

  const rawToken = cryptoPort.randomToken();
  const tokenHash = await cryptoPort.sha256(rawToken);
  const expiresAt = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString();
  await repository.createSession({
    token_hash: tokenHash,
    role: input.view,
    cohort_id: record.cohort_id,
    access_code_id: record.id,
    expires_at: expiresAt,
  });
  await repository.touchCode(record.id, now.toISOString());
  return { token: rawToken, role: input.view, expiresAt };
}

export async function bootstrapHub({ token, now = new Date(), repository, cryptoPort }: any) {
  if (typeof token !== 'string' || token.length < 16 || token.length > 256) throw new Error(SESSION_EXPIRED_MESSAGE);
  const tokenHash = await cryptoPort.sha256(token);
  const session = await repository.findSession(tokenHash);
  if (!isSessionUsable(session, now)) throw new Error(SESSION_EXPIRED_MESSAGE);
  const accessCode = await repository.findAccessCodeById(session.access_code_id);
  if (!isCodeUsable(accessCode, session.role, now) || accessCode.cohort_id !== session.cohort_id) {
    throw new Error(SESSION_EXPIRED_MESSAGE);
  }
  const cohort = await repository.findCohort(session.cohort_id);
  if (!cohort || cohort.status !== 'live') throw new Error(SESSION_EXPIRED_MESSAGE);

  const bundle = prepareBundleForDelivery(await repository.loadCurrentProgramme(session.cohort_id));
  if (!bundle) {
    throw new Error(PROGRAMME_PENDING_MESSAGE);
  }
  await repository.touchSession(session.id, now.toISOString());
  return shapeBootstrap({ role: session.role, ...bundle });
}

export async function saveSharedHubFeedback({token,feedbackType,input,now=new Date(),repository,cryptoPort}:any){if(typeof token!=='string'||token.length<16||token.length>256)throw new Error(SESSION_EXPIRED_MESSAGE);const tokenHash=await cryptoPort.sha256(token);const session=await repository.findSession(tokenHash);if(!isSessionUsable(session,now))throw new Error(SESSION_EXPIRED_MESSAGE);const accessCode=await repository.findAccessCodeById(session.access_code_id);if(!isCodeUsable(accessCode,session.role,now)||accessCode.cohort_id!==session.cohort_id)throw new Error(SESSION_EXPIRED_MESSAGE);const cohort=await repository.findCohortContext(session.cohort_id);if(!cohort||cohort.status!=='live')throw new Error(SESSION_EXPIRED_MESSAGE);const expectedType=session.role==='staff'?'coach_weekly':(feedbackType==='athlete_issue'?'athlete_issue':'athlete_biweekly');const result=await saveFeedback({repository,feedbackType:expectedType,input,cohortId:session.cohort_id,weekNumber:cohort.current_week,replaceExisting:session.role==='staff'});await repository.touchSession(session.id,now.toISOString());return result;}

const FORM_VERSION='1.0';
const ID_PATTERN=/^[A-Za-z0-9-]{16,80}$/;
function requiredOption(value:unknown,allowed:string[]):string{if(typeof value!=='string'||!allowed.includes(value))throw new Error('Invalid feedback information.');return value;}
function optionalText(value:unknown,max=1000):string{if(value==null)return '';if(typeof value!=='string')throw new Error('Invalid feedback information.');return value.trim().slice(0,max);}function requiredText(value:unknown,max=120):string{if(typeof value!=='string'||!value.trim())throw new Error('Invalid feedback information.');return value.trim().slice(0,max);}
function multi(value:unknown,allowed:string[],max=12):string[]{if(!Array.isArray(value)||value.length>max||value.some(item=>typeof item!=='string'||!allowed.includes(item)))throw new Error('Invalid feedback information.');return [...new Set(value)];}
function base(input:any){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Invalid feedback information.');const submissionId=typeof input.submissionId==='string'?input.submissionId.trim():'';if(!ID_PATTERN.test(submissionId)||input.formVersion!==FORM_VERSION)throw new Error('Invalid feedback information.');return{formVersion:FORM_VERSION,submissionId};}
export function normalizeFeedback(type:string,input:any):Record<string,unknown>{const common=base(input);
if(type==='athlete_weekly')return{...common,trainingFeel:requiredOption(input.trainingFeel,['Easy','Good','Hard','Too hard']),completion:requiredOption(input.completion,['All','Most','Some','Very little']),energy:requiredOption(input.energy,['High','Normal','Low']),pain:requiredOption(input.pain,['None','Mild','Moderate','Significant']),improvements:multi(input.improvements,['Speed','Jumping','Strength','Mobility','Coordination','Conditioning','Nothing noticeable yet','Other']),programmeChange:requiredOption(input.programmeChange,['No','Maybe','Yes']),note:optionalText(input.note,1000)};if(type==='athlete_biweekly')return{...common,submitterName:requiredText(input.submitterName),trainingFeel:requiredOption(input.trainingFeel,['Easy','Good','Hard','Too hard']),completion:requiredOption(input.completion,['All','Most','Some','Very little']),energy:requiredOption(input.energy,['High','Normal','Low']),pain:requiredOption(input.pain,['None','Mild','Moderate','Significant']),improvements:multi(input.improvements,['Speed','Jumping','Strength','Mobility','Coordination','Conditioning','Nothing noticeable yet','Other']),programmeChange:requiredOption(input.programmeChange,['No','Maybe','Yes']),note:optionalText(input.note,1000)};
if(type==='parent_weekly')return{...common,completion:requiredOption(input.completion,['All','Most','Some','Very little']),sessionsFeel:requiredOption(input.sessionsFeel,['Too easy','About right','Challenging but manageable','Too difficult']),energy:requiredOption(input.energy,['High','Normal','Low']),pain:requiredOption(input.pain,['None','Mild','Moderate','Significant']),observations:multi(input.observations,['Moving better','Stronger','Jumping better','More coordinated','More confident','More tired than usual','No noticeable change','Other']),enjoyment:requiredOption(input.enjoyment,['Yes','Mostly','Mixed','No']),scheduleChanges:requiredOption(input.scheduleChanges,['No','Yes']),note:optionalText(input.note,1000)};
if(type==='coach_weekly')return{...common,submitterName:requiredText(input.submitterName),completion:requiredOption(input.completion,['All','Most','Some','Very little']),load:requiredOption(input.load,['Easy','Appropriate','Challenging','Too much']),movementQuality:requiredOption(input.movementQuality,['Improved','Same','Worse']),engagement:requiredOption(input.engagement,['Strong','Good','Mixed','Poor']),modified:requiredOption(input.modified,['No','Minor adjustment','Significant adjustment']),pain:requiredOption(input.pain,['None','Mild','Moderate','Significant']),workloadIssue:requiredOption(input.workloadIssue,['No','Minor','Significant']),attention:requiredOption(input.attention,['No','Review','Adjustment needed']),note:optionalText(input.note,1000)};
if(type==='athlete_issue')return{...common,submitterName:optionalText(input.submitterName,120),session:requiredOption(input.session,['Day 1','Day 2','Day 3','Day 4','Optional Day 4','Other']),reason:requiredOption(input.reason,['School / Sport Clash','Pain / Injury','Illness','Travel / Family','Other']),note:optionalText(input.note,1000)};
throw new Error('Invalid feedback information.');}
export function feedbackStatus(type:string,payload:any):'no_change'|'reviewed'|'adjustment_flagged'{
if(type==='athlete_weekly'||type==='athlete_biweekly'){if(payload.pain==='Significant'||payload.trainingFeel==='Too hard'||payload.completion==='Very little'||payload.programmeChange==='Yes')return'adjustment_flagged';if(payload.pain==='Moderate'||payload.trainingFeel==='Hard'||payload.completion==='Some'||payload.energy==='Low'||payload.programmeChange==='Maybe')return'reviewed';return'no_change';}
if(type==='parent_weekly'){if(payload.pain==='Significant'||payload.sessionsFeel==='Too difficult'||payload.completion==='Very little')return'adjustment_flagged';if(payload.pain==='Moderate'||payload.completion==='Some'||payload.energy==='Low'||payload.enjoyment==='Mixed'||payload.enjoyment==='No'||payload.scheduleChanges==='Yes'||payload.observations?.includes('More tired than usual'))return'reviewed';return'no_change';}
if(type==='coach_weekly'){if(payload.pain==='Significant'||payload.load==='Too much'||payload.completion==='Very little'||payload.movementQuality==='Worse'||payload.modified==='Significant adjustment'||payload.workloadIssue==='Significant'||payload.attention==='Adjustment needed')return'adjustment_flagged';if(payload.pain==='Moderate'||payload.load==='Challenging'||payload.completion==='Some'||payload.engagement==='Mixed'||payload.engagement==='Poor'||payload.modified==='Minor adjustment'||payload.workloadIssue==='Minor'||payload.attention==='Review')return'reviewed';return'no_change';}
return payload.reason==='Pain / Injury'?'adjustment_flagged':'reviewed';}
export async function saveFeedback({repository,feedbackType,input,athleteId=null,staffId=null,cohortId=null,weekNumber,replaceExisting=true}:any){const payload=normalizeFeedback(feedbackType,input);const status=feedbackStatus(feedbackType,payload);const duplicate=await repository.findFeedbackBySubmissionId(payload.submissionId);if(duplicate)return{saved:true,id:duplicate.id,status:duplicate.status,duplicate:true};const row={athlete_id:athleteId,staff_id:staffId,cohort_id:cohortId,week_number:weekNumber,feedback_type:feedbackType,payload,status,reviewed_at:null};if(replaceExisting){const existing=await repository.findFeedbackForContext({athleteId,staffId,cohortId,weekNumber,feedbackType});if(existing){const updated=await repository.updateFeedback(existing.id,{payload,status,reviewed_at:null,admin_reply:null});return{saved:true,id:updated.id,status:updated.status,replaced:true};}}const created=await repository.insertFeedback(row);return{saved:true,id:created.id,status:created.status};}

import { loadReviewedBlockExercises } from './workout-delivery.ts';
type SupabaseClient = any;

const PROFESSIONAL_MEMBER_FIELDS = [
